import type { ReactNode } from 'react';
import { safeProps, type ElementProps } from '../internal/props.js';

export function ActivityList(props: ElementProps<'ul'>) {
  return <ul {...safeProps(props)} className="ns-activity-list" />;
}

type ActivityContentProps = {
  title: ReactNode;
  description?: ReactNode;
  meta?: ReactNode;
  status?: ReactNode;
  icon?: ReactNode;
};

type LinkedActivityItemProps = Omit<ElementProps<'a'>, 'title' | 'children'> &
  ActivityContentProps & { href: string };
type StaticActivityItemProps = Omit<ElementProps<'li'>, 'title' | 'children'> &
  ActivityContentProps & { href?: never };
export type ActivityItemProps = LinkedActivityItemProps | StaticActivityItemProps;

function ActivityContent({ title, description, meta, status, icon }: ActivityContentProps) {
  return (
    <>
      {icon ? (
        <div className="ns-activity-icon" aria-hidden="true">
          {icon}
        </div>
      ) : null}
      <div className="ns-activity-content">
        <div className="ns-activity-title">{title}</div>
        {description ? <div className="ns-activity-description">{description}</div> : null}
      </div>
      {status ? <div className="ns-activity-status">{status}</div> : null}
      {meta ? <div className="ns-activity-meta">{meta}</div> : null}
    </>
  );
}

function LinkedActivityItem({
  title,
  description,
  meta,
  status,
  icon,
  ...props
}: LinkedActivityItemProps) {
  return (
    <li className="ns-activity-item">
      <a {...safeProps(props)} className="ns-activity-link">
        <ActivityContent
          title={title}
          description={description}
          meta={meta}
          status={status}
          icon={icon}
        />
      </a>
    </li>
  );
}

export function ActivityItem(props: ActivityItemProps) {
  if (props.href !== undefined) return <LinkedActivityItem {...props} />;
  const { title, description, meta, status, icon, ...rest } = props;
  return (
    <li {...safeProps(rest)} className="ns-activity-item ns-activity-static">
      <ActivityContent
        title={title}
        description={description}
        meta={meta}
        status={status}
        icon={icon}
      />
    </li>
  );
}

'use client';

import { Dialog } from '@base-ui/react/dialog';
import {
  createContext,
  use,
  useCallback,
  useId,
  useState,
  useSyncExternalStore,
  type ReactNode,
} from 'react';
import { safeProps, type ElementProps } from '../internal/props.js';
import { Theme, useThemeSettings } from '../theme.js';

const mobileQuery = '(max-width: 767px)';

function mobileSnapshot() {
  return window.matchMedia(mobileQuery).matches;
}

const desktopSnapshot = () => false;

type ShellState = {
  mobile: boolean;
  mainId: string;
  navigationLabel: string;
  closeNavigation: () => void;
};

const ShellContext = createContext<ShellState | null>(null);

function useShell() {
  const shell = use(ShellContext);
  if (!shell) throw new Error('AppShell parts must be inside AppShell.');
  return shell;
}

export type AppShellProps = ElementProps<'div'> & {
  layout?: 'page' | 'workspace';
  mainId?: string;
  navigationLabel?: string;
  skipLabel?: string;
};

export function AppShell({
  children,
  layout = 'page',
  mainId: providedMainId,
  navigationLabel = 'Workspace navigation',
  skipLabel = 'Skip to main content',
  ...props
}: AppShellProps) {
  const id = useId();
  const mainId = providedMainId ?? `ns-main-${id}`;
  const [open, setOpen] = useState(false);
  const subscribeMobile = useCallback(
    (onChange: () => void) => {
      const query = window.matchMedia(mobileQuery);
      const handleChange = () => {
        if (!query.matches) setOpen(false);
        onChange();
      };
      query.addEventListener('change', handleChange);
      return () => query.removeEventListener('change', handleChange);
    },
    [setOpen],
  );
  const mobile = useSyncExternalStore(subscribeMobile, mobileSnapshot, desktopSnapshot);

  return (
    <ShellContext
      value={{ mobile, mainId, navigationLabel, closeNavigation: () => setOpen(false) }}
    >
      <Dialog.Root open={mobile && open} onOpenChange={setOpen}>
        <div {...safeProps(props)} className="ns-shell" data-layout={layout}>
          <a className="ns-shell-skip" href={`#${mainId}`}>
            {skipLabel}
          </a>
          {children}
        </div>
      </Dialog.Root>
    </ShellContext>
  );
}

export type AppShellSidebarProps = ElementProps<'aside'>;

export function AppShellSidebar({ children, ...props }: AppShellSidebarProps) {
  const { mobile, navigationLabel } = useShell();
  const theme = useThemeSettings();

  // Keep the portal in the tree so Base UI can finish closing across breakpoints.
  return (
    <>
      {!mobile ? (
        <aside {...safeProps(props)} className="ns-shell-sidebar">
          {children}
        </aside>
      ) : null}
      <Dialog.Portal>
        <Theme {...theme}>
          <Dialog.Backdrop className="ns-shell-overlay" />
          <Dialog.Popup className="ns-shell-drawer">
            <div className="ns-shell-drawer-header">
              <Dialog.Title className="ns-shell-drawer-title">{navigationLabel}</Dialog.Title>
              <Dialog.Close className="ns-shell-close" aria-label="Close navigation">
                <svg
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.7"
                  aria-hidden="true"
                >
                  <path d="m6 6 12 12M6 18 18 6" />
                </svg>
              </Dialog.Close>
            </div>
            <aside {...safeProps(props)} className="ns-shell-sidebar">
              {children}
            </aside>
          </Dialog.Popup>
        </Theme>
      </Dialog.Portal>
    </>
  );
}

export function AppShellHeader({ children, ...props }: ElementProps<'header'>) {
  const { mobile } = useShell();
  return (
    <header {...safeProps(props)} className="ns-shell-header">
      {mobile ? (
        <Dialog.Trigger className="ns-shell-mobile-trigger" aria-label="Open navigation">
          <svg
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.7"
            aria-hidden="true"
          >
            <path d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </Dialog.Trigger>
      ) : null}
      <div className="ns-shell-header-content">{children}</div>
    </header>
  );
}

export type AppShellMainProps = Omit<ElementProps<'main'>, 'id'>;

export function AppShellMain(props: AppShellMainProps) {
  const { mainId } = useShell();
  return <main {...safeProps(props)} id={mainId} className="ns-shell-main" tabIndex={-1} />;
}

export function AppShellBrand(props: ElementProps<'div'>) {
  return <div {...safeProps(props)} className="ns-shell-brand" />;
}

export type AppShellNavProps = Omit<ElementProps<'nav'>, 'aria-label' | 'aria-labelledby'> & {
  label: string;
};

export function AppShellNav({ label, children, ...props }: AppShellNavProps) {
  return (
    <nav {...safeProps(props)} aria-label={label} className="ns-shell-nav">
      <p className="ns-shell-nav-label" aria-hidden="true">
        {label}
      </p>
      <div className="ns-shell-nav-items">{children}</div>
    </nav>
  );
}

export type AppShellNavLinkProps = Omit<ElementProps<'a'>, 'aria-current'> & {
  href: string;
  active?: boolean;
  icon?: ReactNode;
};

export function AppShellNavLink({
  href,
  active = false,
  icon,
  children,
  onClick,
  ...props
}: AppShellNavLinkProps) {
  const { closeNavigation } = useShell();
  return (
    <a
      {...safeProps(props)}
      href={href}
      className="ns-shell-nav-link"
      data-active={active || undefined}
      aria-current={active ? 'page' : undefined}
      onClick={(event) => {
        onClick?.(event);
        if (
          !event.metaKey &&
          !event.ctrlKey &&
          !event.shiftKey &&
          !event.altKey &&
          event.button === 0
        )
          closeNavigation();
      }}
    >
      {icon ? (
        <span className="ns-shell-nav-icon" aria-hidden="true">
          {icon}
        </span>
      ) : null}
      <span className="ns-shell-nav-text">{children}</span>
    </a>
  );
}

export function AppShellFooter(props: ElementProps<'footer'>) {
  return <footer {...safeProps(props)} className="ns-shell-footer" />;
}

export type AppShellBodyProps = ElementProps<'div'>;
export function AppShellBody(props: AppShellBodyProps) {
  return <div {...safeProps(props)} className="ns-shell-body" />;
}
export type AppShellDockProps = ElementProps<'div'>;
export function AppShellDock(props: AppShellDockProps) {
  return <div {...safeProps(props)} className="ns-shell-dock" />;
}

'use client';

import { useRef, type ReactNode } from 'react';
import { AlertDialog } from '@base-ui/react/alert-dialog';
import { InfoIcon } from '@phosphor-icons/react/dist/ssr/Info';
import { WarningIcon } from '@phosphor-icons/react/dist/ssr/Warning';
import { CheckCircleIcon } from '@phosphor-icons/react/dist/ssr/CheckCircle';
import type { Icon as Glyph } from '@phosphor-icons/react';
import type { NoCustomStyle } from '../internal/props.js';
import { Theme, useThemeSettings } from '../theme.js';
import { Button } from '../components/button.js';
import { Icon } from '../components/icon.js';
import { DialogFooter } from '../components/dialog-parts.js';

export type ConfirmationSeverity = 'info' | 'success' | 'warning' | 'destructive';
export type ConfirmationDialogProps = NoCustomStyle & {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  severity?: ConfirmationSeverity;
  title: string;
  description: ReactNode;
  actionLabel: string;
  cancelLabel?: string;
  onAction: () => void;
  actionDisabled?: boolean;
  cancelDisabled?: boolean;
  showCloseButton?: boolean;
  icon?: Glyph;
};

/** Applications keep the dialog open until their mutation has actually succeeded. */
export function ConfirmationDialog({
  open,
  onOpenChange,
  severity = 'info',
  title,
  description,
  actionLabel,
  cancelLabel = 'Cancel',
  onAction,
  actionDisabled = false,
  cancelDisabled = false,
  showCloseButton = true,
  icon,
}: ConfirmationDialogProps) {
  const theme = useThemeSettings();
  const cancelRef = useRef<HTMLButtonElement>(null);
  const tone = severity === 'destructive' ? 'danger' : severity;
  const glyph =
    icon ??
    (severity === 'success' ? CheckCircleIcon : severity === 'info' ? InfoIcon : WarningIcon);
  return (
    <AlertDialog.Root
      open={open}
      onOpenChange={(next, details) => {
        if (!next && cancelDisabled) details.cancel();
        else onOpenChange(next);
      }}
    >
      <AlertDialog.Portal>
        <Theme {...theme}>
          <AlertDialog.Backdrop className="ns-dialog-backdrop" />
          <AlertDialog.Popup className="ns-dialog-popup" data-size="sm" initialFocus={cancelRef}>
            <div className="ns-confirmation-heading">
              <Icon glyph={glyph} tone={tone === 'info' ? 'accent' : tone} size="lg" />
              <AlertDialog.Title className="ns-dialog-title">{title}</AlertDialog.Title>
            </div>
            <AlertDialog.Description className="ns-dialog-description">
              {description}
            </AlertDialog.Description>
            <DialogFooter>
              <AlertDialog.Close
                ref={cancelRef}
                disabled={cancelDisabled}
                className="ns-button"
                data-variant="secondary"
              >
                {cancelLabel}
              </AlertDialog.Close>
              <Button
                variant={severity === 'destructive' ? 'danger' : 'primary'}
                disabled={actionDisabled}
                onClick={onAction}
              >
                {actionLabel}
              </Button>
            </DialogFooter>
            {showCloseButton ? (
              <AlertDialog.Close
                disabled={cancelDisabled}
                className="ns-button ns-dialog-dismiss"
                data-variant="ghost"
                aria-label="Close dialog"
              >
                ×
              </AlertDialog.Close>
            ) : null}
          </AlertDialog.Popup>
        </Theme>
      </AlertDialog.Portal>
    </AlertDialog.Root>
  );
}

'use client';

/* eslint-disable jsx-a11y/no-noninteractive-tabindex -- Named scroll regions need a keyboard scroll target independent of their items. */
import { useImperativeHandle, useLayoutEffect, useRef, type ReactNode } from 'react';
import { safeProps, type ElementProps } from '../internal/props.js';

export type ConversationLogProps = ElementProps<'div'> & { label: string; entryCount: number };
/** Append one keyed element per entry. Streaming and older history preserve the reader's position. */
export function ConversationLog({
  label,
  entryCount,
  children,
  ref,
  onScroll,
  ...props
}: ConversationLogProps) {
  const viewport = useRef<HTMLDivElement>(null);
  const content = useRef<HTMLDivElement>(null);
  const previous = useRef<{ count: number; first: Element | null; firstOffset: number } | null>(
    null,
  );
  useImperativeHandle(ref, () => viewport.current!, []);
  function rememberPosition() {
    const first = content.current?.firstElementChild ?? null;
    previous.current = {
      count: entryCount,
      first,
      firstOffset:
        first && viewport.current
          ? first.getBoundingClientRect().top - viewport.current.getBoundingClientRect().top
          : 0,
    };
  }
  useLayoutEffect(() => {
    const scroll = viewport.current;
    const entries = content.current;
    if (!scroll || !entries) return;
    const before = previous.current;
    const first = entries.firstElementChild;
    if (before?.first && first !== before.first && entries.contains(before.first)) {
      // Retained keyed DOM nodes identify a prepend without requiring product IDs.
      const offset = before.first.getBoundingClientRect().top - scroll.getBoundingClientRect().top;
      scroll.scrollTop += offset - before.firstOffset;
    } else if (!before || first !== before.first || entryCount > before.count) {
      const firstNew = entries.children.item(before?.first === first ? before.count : 0);
      if (firstNew) {
        const offset = firstNew.getBoundingClientRect().top - entries.getBoundingClientRect().top;
        scroll.scrollTop = Math.max(offset - 8, 0);
      }
    }
    rememberPosition();
  });
  // Keyboard users must be able to scroll the log without focusing a message.
  return (
    <div
      {...safeProps(props)}
      ref={viewport}
      role="log"
      aria-label={label}
      aria-live="polite"
      tabIndex={0}
      className="ns-conversation-log"
      onScroll={(event) => {
        rememberPosition();
        onScroll?.(event);
      }}
    >
      <div ref={content} className="ns-conversation-content">
        {children}
      </div>
    </div>
  );
}
export type MessageRowProps = ElementProps<'div'> & { side?: 'start' | 'end'; avatar?: ReactNode };
export function MessageRow({ side = 'start', avatar, children, ...props }: MessageRowProps) {
  return (
    <div {...safeProps(props)} className="ns-message-row" data-ns-side={side}>
      {avatar}
      <div className="ns-message-content">{children}</div>
    </div>
  );
}
export type MessageBubbleProps = ElementProps<'div'> & {
  tone?: 'neutral' | 'accent';
  streaming?: boolean;
};
export function MessageBubble({
  tone = 'neutral',
  streaming = false,
  children,
  ...props
}: MessageBubbleProps) {
  return (
    <div {...safeProps(props)} className="ns-message-bubble" data-tone={tone}>
      {children}
      {streaming ? <span className="ns-message-caret" aria-hidden="true" /> : null}
    </div>
  );
}

'use client';

import { useEffect, useMemo, useState, type ReactNode } from 'react';
import {
  flexRender,
  getCoreRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
  type ColumnDef,
  type OnChangeFn,
  type PaginationState,
  type SortingState,
  type VisibilityState,
  type Updater,
} from '@tanstack/react-table';
import { safeProps, type NoCustomStyle } from '../internal/props.js';
import { Button } from '../components/button.js';
import { Input } from '../components/input.js';
import { Select } from '../components/select.js';
import { Skeleton } from '../components/skeleton.js';
import { Checkbox } from '../components/checkbox.js';
import {
  Menu,
  MenuTrigger,
  MenuContent,
  MenuGroup,
  MenuLabel,
  MenuCheckboxItem,
} from '../components/menu.js';

export type DataTableProps<T, TValue = unknown> = NoCustomStyle & {
  label: string;
  columns: ColumnDef<T, TValue>[];
  data: T[];
  mode?: 'client' | 'manual';
  toolbar?: ReactNode;
  emptyState?: ReactNode;
  loading?: boolean;
  pageSizeOptions?: readonly number[];
  initialPageSize?: number;
  pagination?: PaginationState;
  onPaginationChange?: OnChangeFn<PaginationState>;
  sorting?: SortingState;
  onSortingChange?: OnChangeFn<SortingState>;
  rowCount?: number;
  pageCount?: number;
  enableColumnVisibility?: boolean;
  enableRowSelection?: boolean;
  getRowId?: (row: T, index: number) => string;
  isRowSelected?: (row: T) => boolean;
  rowTone?: (row: T) => 'neutral' | 'warning' | 'danger';
};

export type DataTableToolbarProps = NoCustomStyle & {
  searchValue?: string;
  onSearchValueChange?: (value: string) => void;
  searchPlaceholder?: string;
  searchLabel?: string;
  searchDebounceMs?: number;
  children?: ReactNode;
};

function updated<T>(updater: Updater<T>, current: T): T {
  return typeof updater === 'function' ? (updater as (value: T) => T)(current) : updater;
}

export function DataTableToolbar({
  searchValue = '',
  onSearchValueChange,
  searchPlaceholder = 'Search…',
  searchLabel = 'Search records',
  searchDebounceMs = 0,
  children,
}: DataTableToolbarProps) {
  const [draft, setDraft] = useState({ committed: searchValue, value: searchValue });
  const value = draft.committed === searchValue ? draft.value : searchValue;
  useEffect(() => {
    if (!onSearchValueChange || searchDebounceMs <= 0 || value === searchValue) return;
    const timeout = setTimeout(() => onSearchValueChange(value), searchDebounceMs);
    return () => clearTimeout(timeout);
  }, [onSearchValueChange, searchDebounceMs, searchValue, value]);
  return (
    <div className="ns-table-toolbar">
      {onSearchValueChange ? (
        <div className="ns-table-search">
          <Input
            aria-label={searchLabel}
            placeholder={searchPlaceholder}
            value={value}
            onChange={(event) => {
              setDraft({ committed: searchValue, value: event.target.value });
              if (searchDebounceMs <= 0) onSearchValueChange(event.target.value);
            }}
          />
        </div>
      ) : null}
      <div className="ns-table-toolbar-actions">{children}</div>
    </div>
  );
}

/** A controlled or client-managed collection; apps supply records and cell assemblies. */
export function DataTable<T, TValue = unknown>(input: DataTableProps<T, TValue>) {
  const {
    label,
    columns,
    data,
    mode = 'client',
    toolbar,
    emptyState = 'No records match this view.',
    loading = false,
    pageSizeOptions = [10, 20, 50],
    initialPageSize = 10,
    pagination: paginationProp,
    onPaginationChange,
    sorting: sortingProp,
    onSortingChange,
    rowCount,
    pageCount: pageCountProp,
    enableColumnVisibility = true,
    enableRowSelection = false,
    getRowId,
    rowTone,
    isRowSelected,
  } = safeProps(input);
  const [localPagination, setLocalPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: initialPageSize,
  });
  const [localSorting, setLocalSorting] = useState<SortingState>([]);
  const [visibility, setVisibility] = useState<VisibilityState>({});
  const [selection, setSelection] = useState({});
  const pagination = paginationProp ?? localPagination;
  const sorting = sortingProp ?? localSorting;
  const manual = mode === 'manual';
  const changePagination: OnChangeFn<PaginationState> = (value) =>
    onPaginationChange
      ? onPaginationChange(value)
      : setLocalPagination((current) => updated(value, current));
  const changeSorting: OnChangeFn<SortingState> = (value) =>
    onSortingChange
      ? onSortingChange(value)
      : setLocalSorting((current) => updated(value, current));
  const tableColumns = useMemo<ColumnDef<T, TValue>[]>(
    () =>
      enableRowSelection
        ? [
            {
              id: 'select',
              header: ({ table }) => (
                <Checkbox
                  aria-label="Select all visible rows"
                  checked={table.getIsAllPageRowsSelected()}
                  indeterminate={table.getIsSomePageRowsSelected()}
                  onCheckedChange={(value) => table.toggleAllPageRowsSelected(value)}
                />
              ),
              cell: ({ row }) => (
                <Checkbox
                  aria-label="Select row"
                  checked={row.getIsSelected()}
                  onCheckedChange={(value) => row.toggleSelected(value)}
                />
              ),
              enableSorting: false,
              enableHiding: false,
            },
            ...columns,
          ]
        : columns,
    [columns, enableRowSelection],
  );
  const table = useReactTable({
    data,
    columns: tableColumns,
    getCoreRowModel: getCoreRowModel(),
    ...(manual
      ? {}
      : { getPaginationRowModel: getPaginationRowModel(), getSortedRowModel: getSortedRowModel() }),
    ...(getRowId ? { getRowId } : {}),
    ...(rowCount === undefined ? {} : { rowCount }),
    ...(pageCountProp === undefined ? {} : { pageCount: pageCountProp }),
    enableRowSelection,
    manualPagination: manual,
    manualSorting: manual,
    onPaginationChange: changePagination,
    onSortingChange: changeSorting,
    onColumnVisibilityChange: setVisibility,
    onRowSelectionChange: setSelection,
    state: { pagination, sorting, columnVisibility: visibility, rowSelection: selection },
  });
  const total = manual ? (rowCount ?? data.length) : data.length;
  const pageCount = manual
    ? (pageCountProp ?? Math.ceil(total / pagination.pageSize))
    : table.getPageCount();
  const visibleColumns = table.getVisibleLeafColumns().length;
  return (
    <div className="ns-data-table" aria-busy={loading}>
      {toolbar || enableColumnVisibility ? (
        <div className="ns-table-toolbar">
          {toolbar}
          {enableColumnVisibility ? (
            <Menu>
              <MenuTrigger variant="secondary" size="sm">
                Columns
              </MenuTrigger>
              <MenuContent align="end">
                <MenuGroup>
                  <MenuLabel>Visible columns</MenuLabel>
                  {table
                    .getAllLeafColumns()
                    .filter((column) => column.getCanHide())
                    .map((column) => (
                      <MenuCheckboxItem
                        key={column.id}
                        checked={column.getIsVisible()}
                        onCheckedChange={(visible) => column.toggleVisibility(visible)}
                      >
                        {typeof column.columnDef.header === 'string'
                          ? column.columnDef.header
                          : column.id.replaceAll('_', ' ')}
                      </MenuCheckboxItem>
                    ))}
                </MenuGroup>
              </MenuContent>
            </Menu>
          ) : null}
        </div>
      ) : null}
      <div className="ns-data-table-scroll">
        <table className="ns-table" aria-label={label}>
          <thead>
            {table.getHeaderGroups().map((group) => (
              <tr key={group.id}>
                {group.headers.map((header) => (
                  <th
                    key={header.id}
                    scope="col"
                    aria-sort={
                      header.column.getIsSorted() === 'asc'
                        ? 'ascending'
                        : header.column.getIsSorted() === 'desc'
                          ? 'descending'
                          : undefined
                    }
                  >
                    {header.isPlaceholder ? null : header.column.getCanSort() ? (
                      <button
                        type="button"
                        className="ns-table-sort"
                        onClick={header.column.getToggleSortingHandler()}
                      >
                        {flexRender(header.column.columnDef.header, header.getContext())}
                        <span aria-hidden="true">
                          {header.column.getIsSorted() === 'asc'
                            ? '↑'
                            : header.column.getIsSorted() === 'desc'
                              ? '↓'
                              : '↕'}
                        </span>
                      </button>
                    ) : (
                      flexRender(header.column.columnDef.header, header.getContext())
                    )}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody>
            {loading ? (
              Array.from({ length: Math.min(pagination.pageSize, 5) }, (_, index) => (
                <tr key={index}>
                  {Array.from({ length: visibleColumns }, (_, cell) => (
                    <td key={cell}>
                      <Skeleton size="sm" />
                    </td>
                  ))}
                </tr>
              ))
            ) : table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => (
                <tr
                  key={row.id}
                  data-selected={row.getIsSelected() || isRowSelected?.(row.original) || false}
                  aria-selected={row.getIsSelected() || isRowSelected?.(row.original) || false}
                  data-tone={rowTone?.(row.original) ?? 'neutral'}
                >
                  {row.getVisibleCells().map((cell) => (
                    <td key={cell.id}>
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </td>
                  ))}
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan={visibleColumns}>
                  <div className="ns-table-empty">{emptyState}</div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
      <div className="ns-table-footer">
        <span>
          {enableRowSelection
            ? `${table.getSelectedRowModel().rows.length} of ${total} selected`
            : `${total} records`}
        </span>
        <div className="ns-table-toolbar-actions">
          <span>
            Page {pageCount === 0 ? 0 : pagination.pageIndex + 1} of {pageCount}
          </span>
          <div className="ns-table-page-size">
            <Select
              aria-label="Rows per page"
              size="sm"
              value={String(pagination.pageSize)}
              options={pageSizeOptions.map((size) => ({
                value: String(size),
                label: `${size} per page`,
              }))}
              onChange={(event) =>
                changePagination({ pageIndex: 0, pageSize: Number(event.target.value) })
              }
            />
          </div>
          <Button
            variant="secondary"
            size="sm"
            disabled={pagination.pageIndex <= 0}
            onClick={() => changePagination({ ...pagination, pageIndex: pagination.pageIndex - 1 })}
          >
            Previous
          </Button>
          <Button
            variant="secondary"
            size="sm"
            disabled={pagination.pageIndex + 1 >= pageCount}
            onClick={() => changePagination({ ...pagination, pageIndex: pagination.pageIndex + 1 })}
          >
            Next
          </Button>
        </div>
      </div>
    </div>
  );
}

