}
.ns-heading[data-size='lg'] {
  font-size: 16px;
}
.ns-heading[data-size='xl'] {
  font-size: 22px;
}
.ns-heading[data-size='2xl'] {
  font-size: 28px;
}
.ns-stack {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.ns-stack[data-align='start'] {
  align-items: flex-start;
}
.ns-stack[data-align='center'] {
  align-items: center;
}
.ns-stack[data-align='stretch'] {
  align-items: stretch;
}
.ns-cluster {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  min-width: 0;
}
.ns-cluster[data-justify='between'] {
