}
.ns-stack[data-gap='none'],
.ns-cluster[data-gap='none'] {
  gap: var(--ns-space-none);
}
.ns-stack[data-gap='xs'],
.ns-cluster[data-gap='xs'],
.ns-grid[data-gap='xs'] {
  gap: var(--ns-space-xs);
}
.ns-stack[data-gap='sm'],
.ns-cluster[data-gap='sm'],
.ns-grid[data-gap='sm'] {
  gap: var(--ns-space-sm);
}
.ns-stack[data-gap='md'],
.ns-cluster[data-gap='md'],
.ns-grid[data-gap='md'] {
  gap: var(--ns-space-md);
}
.ns-stack[data-gap='lg'],
.ns-cluster[data-gap='lg'],
.ns-grid[data-gap='lg'] {
  gap: var(--ns-space-lg);
}
.ns-stack[data-gap='xl'],
.ns-cluster[data-gap='xl'],
.ns-grid[data-gap='xl'] {
  gap: var(--ns-space-xl);
}
.ns-divider {
