  border-radius: 12px;
  background: var(--ns-surface);
}
.ns-surface[data-tone='subtle'] {
  background: var(--ns-subtle);
}
.ns-surface[data-padding='none'] {
  padding: 0;
}
.ns-surface[data-padding='sm'] {
  padding: 8px;
}
.ns-surface[data-padding='md'] {
  padding: 16px;
}
.ns-surface[data-padding='lg'] {
  padding: 24px;
}
.ns-skeleton {
  background: var(--ns-hover);
  border-radius: 4px;
  min-height: 16px;
  width: 100%;
  animation: ns-pulse 1.8s ease-in-out infinite;
}
.ns-skeleton[data-shape='circle'] {
  border-radius: 50%;
  width: 36px;
  height: 36px;
}
.ns-skeleton[data-shape='block'] {
  min-height: 96px;
  border-radius: 8px;
}
.ns-skeleton[data-size='sm'] {
  max-width: 120px;
}
.ns-skeleton[data-size='md'] {
  max-width: 240px;
}
@keyframes ns-pulse {
  50% {
    opacity: 0.55;
  }
}
.ns-input {
  display: block;
  width: 100%;
  min-height: 36px;
  padding: 7px 10px;
  background: var(--ns-surface);
  color: var(--ns-text);
  border: 1px solid var(--ns-control-border);
  border-radius: 6px;
  font: inherit;
}
.ns-input[data-size='sm'] {
  min-height: 32px;
  font-size: 12px;
}
.ns-select[data-ns-width='content'] {
  width: auto;
  max-width: 100%;
}
.ns-input::placeholder {
  color: var(--ns-muted);
}
.ns-input[aria-invalid='true'] {
  border-color: var(--ns-danger);
}
.ns-input:disabled {
