  max-width: 100%;
  overflow-x: auto;
}
.ns-tabs-tab {
  min-height: 32px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--ns-muted);
  font: inherit;
  font-size: 13px;
  padding: 6px 12px;
  white-space: nowrap;
  cursor: pointer;
}
.ns-tabs-tab[data-active] {
  background: var(--ns-surface);
  color: var(--ns-text);
  box-shadow: 0 1px 3px #0000000c;
}
.ns-tabs-tab:disabled {
