  cursor: not-allowed;
}
.ns-tabs-panel {
  padding-top: 20px;
}
.ns-dialog-backdrop,
.ns-shell-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: #050d1c80;
}
.ns-dialog-popup {
  position: fixed;
  z-index: 101;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: min(520px, calc(100vw - 32px));
  max-height: calc(100dvh - 48px);
  overflow-y: auto;
  padding: 24px;
  border-radius: 12px;
  background: var(--ns-surface);
  color: var(--ns-text);
  box-shadow: var(--ns-shadow);
}
.ns-dialog-popup[data-size='sm'] {
  width: min(400px, calc(100vw - 32px));
}
.ns-dialog-title {
  margin: 0 0 8px;
  font-size: 20px;
  font-weight: 600;
}
.ns-dialog-description {
  margin: 0 0 24px;
  color: var(--ns-muted);
}
.ns-shell {
  display: grid;
  grid-template-columns: 224px minmax(0, 1fr);
  grid-template-rows: auto 1fr;
  min-height: 100dvh;
  background: var(--ns-canvas);
}
.ns-shell-sidebar {
  grid-column: 1;
  grid-row: 1 / -1;
  display: flex;
  flex-direction: column;
  gap: 24px;
  background: var(--ns-canvas);
  padding: 24px 12px 16px;
  border-right: 1px solid var(--ns-border);
}
.ns-shell-brand {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  padding: 0 10px 8px;
  font-size: 17px;
  font-weight: 650;
  letter-spacing: -0.025em;
}
.ns-shell-brand svg {
  width: 24px;
  height: 24px;
  color: var(--ns-accent);
}
.ns-shell-nav {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.ns-shell-nav-link {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 36px;
  padding: 8px 10px;
  border-radius: 6px;
  color: var(--ns-muted);
  font-weight: 500;
  text-decoration: none;
  font-size: 13px;
  overflow-wrap: anywhere;
}
.ns-shell-nav-link:hover {
  color: var(--ns-text);
  background: var(--ns-hover);
}
.ns-shell-nav-link[aria-current='page'] {
  color: var(--ns-text);
  background: var(--ns-hover);
}
.ns-shell-nav-link > svg,
.ns-shell-nav-link > span > svg {
  width: 17px;
  height: 17px;
}
.ns-shell-footer {
  margin-top: auto;
  padding: 12px 10px 0;
}
.ns-shell-header {
  grid-column: 2;
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 64px;
  padding: 12px 32px;
  border-bottom: 1px solid var(--ns-border);
  background: var(--ns-surface);
}
.ns-shell-header-content {
  flex: 1;
  min-width: 0;
}
.ns-shell-main {
  grid-column: 2;
  min-width: 0;
  padding: 36px 40px 56px;
}
.ns-shell-main > * {
  max-width: 1280px;
  margin-inline: auto;
}
.ns-shell-mobile-trigger {
  display: none;
}
.ns-shell-drawer {
  position: fixed;
  z-index: 101;
  inset: 0 auto 0 0;
  width: min(300px, calc(100vw - 48px));
  overflow-y: auto;
  background: var(--ns-canvas);
  box-shadow: var(--ns-shadow);
  padding: 24px 12px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}
.ns-shell-drawer-title {
  font-size: 14px;
  margin: 0;
}
.ns-page-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
  padding-bottom: 28px;
}
.ns-page-header-title {
  margin: 0;
  font-size: 28px;
  line-height: 1.25;
  font-weight: 600;
  letter-spacing: -0.025em;
  text-wrap: balance;
  overflow-wrap: anywhere;
}
.ns-page-header-description {
  margin: 6px 0 0;
  color: var(--ns-muted);
  max-width: 65ch;
}
.ns-page-header-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding-top: 2px;
}
.ns-section {
  min-width: 0;
}
.ns-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}
.ns-section-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.4;
}
.ns-section-description {
  margin: 4px 0 0;
  font-size: 12px;
  color: var(--ns-muted);
}
.ns-section-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.ns-section-body {
  min-width: 0;
}
.ns-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 40px 24px;
  text-align: center;
}
.ns-empty-icon {
  color: var(--ns-muted);
  margin-bottom: 16px;
}
.ns-empty-icon svg {
  width: 28px;
  height: 28px;
}
.ns-empty-title {
  margin: 0;
  font-size: 15px;
  font-weight: 550;
}
.ns-empty-description {
  margin: 8px 0 0;
  color: var(--ns-muted);
  max-width: 48ch;
}
.ns-empty-action {
  margin-top: 20px;
}
.ns-metric {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 20px;
  background: var(--ns-surface);
  border: 1px solid var(--ns-border);
  border-radius: 10px;
}
.ns-metric-label {
  margin: 0;
  color: var(--ns-muted);
  font-size: 12px;
  font-weight: 500;
}
.ns-metric-value {
  margin: 0;
  font-size: 26px;
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.025em;
  overflow-wrap: anywhere;
}
.ns-metric-hint {
  margin: 2px 0 0;
  color: var(--ns-muted);
  font-size: 12px;
}
.ns-metric[data-tone='success'] .ns-metric-value {
  color: var(--ns-success);
}
.ns-metric[data-tone='danger'] .ns-metric-value {
  color: var(--ns-danger);
}
.ns-metric[data-tone='warning'] .ns-metric-value {
  color: var(--ns-warning);
}
.ns-metric[data-tone='info'] .ns-metric-value {
  color: var(--ns-accent);
}
.ns-activity-list {
  list-style: none;
  padding: 0;
  margin: 0;
}
.ns-activity-item {
  margin: 0;
}
.ns-activity-item + .ns-activity-item {
  border-top: 1px solid var(--ns-border);
}
.ns-activity-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: var(--ns-row-padding);
  min-width: 0;
  color: var(--ns-text);
  text-decoration: none;
}
a.ns-activity-link:hover {
  background: var(--ns-subtle);
}
.ns-activity-icon {
  color: var(--ns-muted);
  display: flex;
  align-items: center;
  justify-content: center;
}
.ns-activity-icon svg {
  width: 20px;
  height: 20px;
}
.ns-activity-content {
  flex: 1;
  min-width: 0;
}
.ns-activity-title {
  display: block;
  font-size: 13px;
  font-weight: 550;
  overflow-wrap: anywhere;
}
.ns-activity-description {
  display: block;
  margin-top: 3px;
  font-size: 12px;
  color: var(--ns-muted);
  overflow-wrap: anywhere;
}
.ns-activity-meta {
  color: var(--ns-muted);
  font-size: 12px;
  white-space: nowrap;
}
.ns-activity-status {
  display: flex;
  align-items: center;
}
@media (max-width: 1000px) {
  .ns-shell {
    grid-template-columns: 196px minmax(0, 1fr);
  }
  .ns-shell-main {
    padding: 28px 24px 40px;
  }
  .ns-shell-header {
    padding-inline: 24px;
  }
}
@media (max-width: 767px) {
  .ns-shell {
    grid-template-columns: minmax(0, 1fr);
  }
  .ns-shell-sidebar {
    display: none;
  }
  .ns-shell-header,
  .ns-shell-main {
    grid-column: 1;
  }
  .ns-shell-header {
    min-height: 60px;
    padding: 12px 16px;
  }
  .ns-shell-main {
    padding: 24px 16px 40px;
  }
  .ns-shell-mobile-trigger {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 36px;
    padding: 7px 10px;
    border: 1px solid var(--ns-border);
    border-radius: 6px;
    background: var(--ns-surface);
    color: var(--ns-text);
    font: inherit;
    font-size: 12px;
    cursor: pointer;
  }
  .ns-grid[data-responsive='true'] {
    grid-template-columns: minmax(0, 1fr);
  }
  .ns-page-header {
    padding-bottom: 24px;
  }
  .ns-page-header-title {
    font-size: 25px;
  }
  .ns-activity-link,
  .ns-activity-static {
    display: grid;
    grid-template-columns: 20px minmax(0, 1fr) auto;
    gap: 8px 12px;
  }
  .ns-activity-icon {
    grid-column: 1;
    grid-row: 1;
  }
  .ns-activity-content {
    grid-column: 2;
    grid-row: 1;
  }
  .ns-activity-status {
    grid-column: 3;
    grid-row: 1;
  }
  .ns-activity-meta {
    grid-column: 2 / -1;
    grid-row: 2;
    justify-self: start;
  }

  .ns-metric {
    padding: 16px;
  }
}
@media (pointer: coarse) {
  .ns-button,
  .ns-button[data-size],
  .ns-tabs-tab,
  .ns-shell-nav-link,
  .ns-shell-mobile-trigger {
    min-height: 44px;
  }
  .ns-input,
  .ns-input[data-size] {
    min-height: 44px;
    font-size: 16px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ns-button {
    transition: none;
  }
  .ns-skeleton {
    animation: none;
  }
}
@media (forced-colors: active) {
  .ns-button,
  .ns-badge,
  .ns-tabs-tab[data-active],
  .ns-shell-nav-link[aria-current='page'] {
    border: 1px solid ButtonText;
  }
}
.ns-shell-skip {
  position: fixed;
  top: 8px;
  left: 8px;
  z-index: 200;
  padding: 8px 16px;
  background: var(--ns-surface);
  color: var(--ns-accent);
  transform: translateY(-160%);
}
.ns-shell-skip:focus {
  transform: translateY(0);
}
.ns-shell-nav-label {
  margin: 0 10px 8px;
  color: var(--ns-muted);
  font-size: 11px;
  font-weight: 500;
}
.ns-shell-nav-items {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.ns-shell-nav-icon {
  display: inline-flex;
}
.ns-shell-nav-text {
  min-width: 0;
}
.ns-shell-drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.ns-shell-drawer .ns-shell-sidebar {
  display: flex;
  border: 0;
  padding: 0;
  flex: 1;
}
.ns-shell-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: 0;
  border-radius: 6px;
  color: var(--ns-muted);
  background: transparent;
  cursor: pointer;
}
.ns-shell-close:hover {
  background: var(--ns-hover);
}
.ns-shell-close svg,
.ns-shell-mobile-trigger svg {
  width: 20px;
  height: 20px;
}
.ns-activity-static {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: var(--ns-row-padding);
  min-width: 0;
}
.ns-dialog-dismiss {
  position: absolute;
  top: 12px;
  right: 12px;
}
.ns-dialog-title {
  padding-right: 32px;
}

.ns-status-marker {
  --ns-status-color: var(--ns-muted);
  --ns-status-fill: var(--ns-subtle);
  display: inline-flex;
  flex-shrink: 0;
