  font-weight: 500;
  line-height: 1.4;
  color: var(--ns-status-color);
}
.ns-status-marker[data-tone='info'] {
  --ns-status-color: var(--ns-accent);
  --ns-status-fill: var(--ns-accent-soft);
}
.ns-status-marker[data-tone='success'] {
  --ns-status-color: var(--ns-success);
  --ns-status-fill: var(--ns-success-soft);
}
.ns-status-marker[data-tone='warning'] {
  --ns-status-color: var(--ns-warning);
  --ns-status-fill: var(--ns-warning-soft);
}
.ns-status-marker[data-tone='danger'] {
  --ns-status-color: var(--ns-danger);
  --ns-status-fill: var(--ns-danger-soft);
}
.ns-status-marker[data-variant='pill'] {
  border: 1px solid color-mix(in oklab, var(--ns-status-color) 25%, transparent);
