}
.ns-timeline-item {
  display: block;
  width: 100%;
  min-width: 0;
  padding: 12px 16px;
  border: 0;
  border-bottom: 1px solid var(--ns-border);
  background: transparent;
  color: var(--ns-text);
  text-align: start;
  font: inherit;
  cursor: pointer;
}
.ns-timeline-item:hover {
  background: var(--ns-subtle);
}
.ns-timeline-item[data-selected='true'] {
  background: var(--ns-accent-soft);
}
.ns-timeline-item:focus-visible {
  outline: 2px solid var(--ns-accent);
  outline-offset: -2px;
}
.ns-timeline-heading {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
}
.ns-timeline-label {
