/*
 * The runner character.
 *
 * Three inputs drive everything and none of them go through React per frame:
 * `--bot-load` is how full the worker is, `--bot-phase` offsets it from its
 * neighbours, and `--bot-size` is how big it is drawn. Colour is the app
 * palette throughout, so the character inherits light and dark without knowing
 * about either.
 */

.ns-worker-avatar {
  /* One period drives every working motion, and the period is the load: a
     worker at 0.17 works on a 1.5s beat, a saturated one on a 0.6s beat. */
  --bot-beat: calc(1.7s - var(--bot-load, 0) * 1.1s);

  width: 2.75rem;
  flex: none;
  height: auto;
  overflow: visible;
}

.ns-worker-avatar * {
  transform-box: fill-box;
}

/* ------------------------------------------------------------------ body */

.ns-worker-avatar-shell {
  fill: color-mix(in oklab, var(--ns-surface) 88%, var(--ns-text) 12%);
  stroke: color-mix(in oklab, var(--ns-text) 22%, transparent);
  stroke-width: 1.6;
}

.ns-worker-avatar-visor {
  fill: color-mix(in oklab, var(--ns-text) 86%, transparent);
  transition: fill 260ms cubic-bezier(0.22, 1, 0.32, 1);
}

.ns-worker-avatar-eye {
  fill: var(--ns-accent);
  transition: fill 260ms cubic-bezier(0.22, 1, 0.32, 1);
}

.ns-worker-avatar-stalk {
  fill: none;
  stroke: color-mix(in oklab, var(--ns-text) 22%, transparent);
  stroke-width: 3;
  stroke-linecap: round;
}

.ns-worker-avatar-bulb {
  fill: var(--ns-accent);
  transition: fill 260ms cubic-bezier(0.22, 1, 0.32, 1);
}

.ns-worker-avatar-shadow {
  fill: var(--ns-text);
  opacity: 0.08;
}

/* ------------------------------------------------------------------ eyes */

/* The eyes narrow as the worker fills up. A plain transform, not an
   animation, so concentration survives reduced motion. */
.ns-worker-avatar-eyes {
  transform-origin: 50% 50%;
  transform: scaleY(calc(1 - var(--bot-load, 0) * 0.34));
  transition: transform 420ms cubic-bezier(0.22, 1, 0.32, 1);
}

.ns-worker-avatar[data-alarmed='true'] .ns-worker-avatar-visor {
  fill: var(--ns-danger);
}

.ns-worker-avatar[data-alarmed='true'] .ns-worker-avatar-eye {
  fill: var(--ns-surface);
}

.ns-worker-avatar[data-alarmed='true'] .ns-worker-avatar-bulb {
  fill: var(--ns-danger);
}

/* ----------------------------------------------------------- event motion */

/* Keyed on the observed value, so the ring emits once per real event and
   never on a timer. */
.ns-worker-avatar-beat {
  fill: none;
  stroke: var(--ns-accent);
  stroke-width: 2.5;
  opacity: 0;
  transform-origin: 50% 50%;
  animation: ns-worker-avatar-emit 1.05s cubic-bezier(0.15, 0.7, 0.3, 1) 1;
}

.ns-worker-avatar[data-alarmed='true'] .ns-worker-avatar-beat {
  stroke: var(--ns-danger);
}

@keyframes ns-worker-avatar-emit {
  0% {
    transform: scale(0.28);
    opacity: 0;
  }
  14% {
    opacity: 0.85;
  }
  100% {
    transform: scale(1);
    opacity: 0;
  }
}

/* Something moved. One squash, then rest. */
.ns-worker-avatar-react[data-react='jolt'] {
  transform-origin: 50% 100%;
  animation: ns-worker-avatar-jolt 0.46s cubic-bezier(0.22, 1, 0.32, 1) 1;
}

@keyframes ns-worker-avatar-jolt {
  0% {
    transform: scale(1, 1);
  }
  22% {
    transform: scale(1.09, 0.9);
  }
  52% {
    transform: scale(0.97, 1.05);
  }
  100% {
    transform: scale(1, 1);
  }
}

/*
 * The alarm shakes three times, then stops. An alarm that never stops shaking
 * is one people learn to ignore, and the red visor holds the state after the
 * movement is over.
 */
.ns-worker-avatar-react[data-react='alarm'] {
  transform-origin: 50% 100%;
  animation: ns-worker-avatar-alarm 0.4s cubic-bezier(0.36, 0.07, 0.19, 0.97) 3;
}

@keyframes ns-worker-avatar-alarm {
  0%,
  100% {
    transform: translateX(0) rotate(0deg);
  }
  25% {
    transform: translateX(-2.5px) rotate(-2.5deg);
  }
  75% {
    transform: translateX(2.5px) rotate(2.5deg);
  }
}

/* ---------------------------------------------------------- working motion */

/* Eyes dart across the visor and dwell at each end, the way something reading
   a list moves. A smooth sweep reads as a machine part; a dwell reads as
   attention. */
.ns-worker-avatar[data-working='true'] .ns-worker-avatar-pupils {
  animation: ns-worker-avatar-read var(--bot-beat) ease-in-out infinite;
  animation-delay: calc(var(--bot-phase, 0) * -2s);
}

@keyframes ns-worker-avatar-read {
  0%,
  28% {
    transform: translateX(-3.4px);
  }
  46%,
  76% {
    transform: translateX(3.4px);
  }
  94%,
  100% {
    transform: translateX(-3.4px);
  }
}

/* The body dips twice per pass — effort, and the amplitude is the load. */
.ns-worker-avatar[data-working='true'] .ns-worker-avatar-rig {
  transform-origin: 50% 100%;
  animation: ns-worker-avatar-effort var(--bot-beat) ease-in-out infinite;
  animation-delay: calc(var(--bot-phase, 0) * -2s);
}

@keyframes ns-worker-avatar-effort {
  0%,
  50%,
  100% {
    transform: translateY(0) scaleY(1);
  }
  25%,
  75% {
    transform: translateY(calc(0.5px + var(--bot-load, 0) * 1.3px))
      scaleY(calc(1 - var(--bot-load, 0) * 0.018));
  }
}

/* Secondary motion: the antenna lags the dip instead of moving with it. This
   one delay is most of what separates a living character from a moving shape. */
.ns-worker-avatar[data-working='true'] .ns-worker-avatar-antenna {
  transform-origin: 50% 100%;
  animation: ns-worker-avatar-trail var(--bot-beat) ease-in-out infinite;
  animation-delay: calc(var(--bot-phase, 0) * -2s + var(--bot-beat) * 0.12);
}

@keyframes ns-worker-avatar-trail {
  0%,
  50%,
  100% {
    transform: rotate(0deg);
  }
  25% {
    transform: rotate(calc(var(--bot-load, 0) * -4deg));
  }
  75% {
    transform: rotate(calc(var(--bot-load, 0) * 4deg));
  }
}

/*
 * Steam, in steps: one vent opens at half load, two at three quarters, three
 * at full. Only the opened vents are drawn, so the number of plumes on screen
 * is the reading.
 *
 * A machine under load runs hot rather than perspiring, and steam belongs off
 * the body — rising, spreading and thinning out — which is why it sits well
 * above the crown instead of clinging to a flank.
 *
 * The cycle tightens with load, from 3.4s down to 2.2s, and each vent is
 * offset by a third of it so the plumes leave in turn rather than together.
 */
.ns-worker-avatar-steam {
  fill: var(--ns-warning);
  opacity: 0;
  transform-origin: 50% 100%;
  /* The filtered cluster is the expensive pixel work. Promoting the animated
     wrapper keeps that raster cached and leaves the frame to a composite. */
  will-change: transform, opacity;
  animation: ns-worker-avatar-steam calc(3.4s - var(--bot-load, 0) * 1.2s) linear infinite;
  animation-delay: calc(
    (var(--puff, 0) / 3 + var(--bot-phase, 0)) * (var(--bot-load, 0) * 1.2s - 3.4s)
  );
}

/*
 * Steam thins as it expands: the puff nearly triples in size on the way up and
 * loses opacity faster than it gains height, so it dissipates rather than
 * simply sliding off the top.
 */
@keyframes ns-worker-avatar-steam {
  0% {
    opacity: 0;
    transform: translate(0, 2px) rotate(0deg) scale(0.3);
    animation-timing-function: cubic-bezier(0.15, 0.65, 0.4, 1);
  }
  22% {
    opacity: 0.8;
    transform: translate(
        calc(var(--steam-drift-x, 9px) * 0.18),
        calc(var(--steam-rise-y, 30px) * -0.22)
      )
      rotate(calc(var(--steam-spin, 26deg) * 0.25)) scale(0.9, 0.8);
    animation-timing-function: linear;
  }
  58% {
    opacity: 0.55;
    transform: translate(
        calc(var(--steam-drift-x, 9px) * 0.6),
        calc(var(--steam-rise-y, 30px) * -0.62)
      )
      rotate(calc(var(--steam-spin, 26deg) * 0.65)) scale(1.75, 1.5);
    animation-timing-function: cubic-bezier(0.4, 0, 0.7, 0.6);
  }
  100% {
    opacity: 0;
    transform: translate(var(--steam-drift-x, 9px), calc(var(--steam-rise-y, 30px) * -1))
      rotate(var(--steam-spin, 26deg)) scale(3.1, 2.4);
  }
}

@media (prefers-reduced-motion: reduce) {
  .ns-worker-avatar-beat,
  .ns-worker-avatar-react,
  .ns-worker-avatar-pupils,
  .ns-worker-avatar-antenna,
  .ns-worker-avatar-rig,
  .ns-worker-avatar-steam {
    animation: none !important;
  }

  .ns-worker-avatar-visor,
  .ns-worker-avatar-eye,
  .ns-worker-avatar-bulb,
  .ns-worker-avatar-eyes {
    transition-duration: 1ms;
  }

  /* The reading survives the motion: each plume holds part way up its climb,
     already spread and turned, so how many there are still answers how hard
     the worker is going. */
  .ns-worker-avatar-steam {
    opacity: 0.55;
    transform: translate(
        calc(var(--steam-drift-x, 9px) * 0.45),
        calc(var(--steam-rise-y, 30px) * -0.45)
      )
      rotate(calc(var(--steam-spin, 26deg) * 0.5)) scale(1.35);
  }
}

.ns-worker-avatar[data-size='sm'] {
  width: 1.9rem;
}
.ns-worker-avatar[data-size='lg'] {
  width: 3.5rem;
}

'use client';

import { createContext, use } from 'react';
import { safeProps, type ElementProps } from './internal/props.js';

export type ColorScheme = 'light' | 'dark';
export type Brand = 'nanostack' | 'echopoint' | 'anchor';
export type Density = 'comfortable' | 'compact';
export type ThemeSettings = { colorScheme: ColorScheme; brand: Brand; density: Density };
const defaultTheme: ThemeSettings = {
  colorScheme: 'light',
  brand: 'nanostack',
  density: 'comfortable',
};
const ThemeContext = createContext<ThemeSettings>(defaultTheme);
export type ThemeProps = ElementProps<'div'> & Partial<ThemeSettings>;

export function Theme({
  colorScheme = 'light',
  brand = 'nanostack',
  density = 'comfortable',
  children,
  ...props
}: ThemeProps) {
  return (
    <ThemeContext value={{ colorScheme, brand, density }}>
      <div
        {...safeProps(props)}
        className="ns-theme"
        data-ns-theme={colorScheme}
        data-ns-brand={brand}
        data-ns-density={density}
      >
        {children}
      </div>
    </ThemeContext>
  );
}

/** Internal overlays inherit the nearest scope even when portalled to body. */
export function useThemeSettings() {
  return use(ThemeContext);
}
